class Solution {
public:
    int winningPlayerCount(int n, vector<vector<int>>& pick) {
        vector<vector<int>> counts(n, vector<int>(11, 0));
        for (const auto& p : pick) {
            counts[p[0]][p[1]]++;
        }
        int winners = 0;
        for (int i = 0; i < n; ++i) {
            bool win = false;
            for (int c = 0; c <= 10; ++c) {
                if (counts[i][c] > i) {
                    win = true;
                    break;
                }
            }
            if (win) winners++;
        }
        return winners;
    }
};

class Solution {
    public int winningPlayerCount(int n, int[][] pick) {
        int[][] counts = new int[n][11];
        for (int[] p : pick) {
            counts[p[0]][p[1]]++;
        }
        int winners = 0;
        for (int i = 0; i < n; ++i) {
            for (int c = 0; c <= 10; ++c) {
                if (counts[i][c] > i) {
                    winners++;
                    break;
                }
            }
        }
        return winners;
    }
}

var winningPlayerCount = function(n, pick) {
    const counts = Array.from({ length: n }, () => new Array(11).fill(0));
    for (const [p, c] of pick) {
        counts[p][c]++;
    }
    let winners = 0;
    for (let i = 0; i < n; i++) {
        for (let c = 0; c <= 10; c++) {
            if (counts[i][c] > i) {
                winners++;
                break;
            }
        }
    }
    return winners;
};
